    add(1, "id",
        title="Fungsi tangan pada stroke akut: uji acak latihan berbantuan robot di Rumah Sakit NP Brain",
        desc="Uji acak 30 pasien di Rumah Sakit NP Brain: latihan tangan berbantuan robot ditambahkan pada terapi neurodevelopmental. Temuan Nine-Hole Peg, ABILHAND, dan Barthel adalah hasil studi.",
        lead="Setelah stroke, tangan sering kembali ke tugas harian lebih lambat daripada berjalan: cangkir, kancing, atau alat makan menjadi hambatan yang nyata. Jendela akut berubah cepat, jadi apa yang ditambahkan di situ perlu perbandingan acak, bukan kesan satu kasus. Pada 2026 Scientific Reports menerbitkan uji acak dari Rumah Sakit NP Brain di Turki yang menambahkan latihan tangan berbantuan robot Syrebo pada terapi neurodevelopmental biasa. Artikel melaporkan peningkatan yang lebih besar pada ketangkasan, aktivitas dua tangan, dan perawatan diri dibanding terapi saja. Sampelnya 30 orang, dan spastisitas tidak memisahkan kelompok.",
        bg=[
            "Tangan sulit karena membutuhkan kekuatan, gerakan yang terpisah, dan pemakaian yang nyata. Berjalan dapat dilatih sebagai satu sasaran; tangan harus menggenggam dan melepas di dalam postur yang tidak stabil. Terapi neurodevelopmental sudah menjadi dasar rehabilitasi akut, tetapi terapis tidak dapat mengulang setiap genggaman tanpa batas, jadi dosis dan keteraturan sulit diperlebar.",
            "Sarung tangan robotik lunak pada prinsipnya dapat menyediakan pengulangan itu di bawah pengawasan. Pasien akut masih berubah. Apakah alat dapat ditambahkan dengan aman, dan apakah skor fungsi ikut bergerak, adalah pertanyaan yang terkontrol. Uji ini membahas tahap itu, bukan mengulang studi fase kronik.",
        ],
        device="Artikel menamai alat sebagai tangan robotik SYREBO. Foto menunjukkan sarung tangan lunak, konsol, dan tablet agar pembaca melihat bentuknya. Rincian model milik artikel dan protokol klinis.",
        design="Perbandingan acak di satu pusat. Satu kelompok menerima latihan tangan berbantuan robot ditambah terapi neurodevelopmental (NT). Kelompok kontrol hanya menerima NT. Luaran adalah ketangkasan halus, aktivitas harian dua tangan, dan perawatan diri, bukan kekuatan semata.",
        sample="Rumah Sakit NP Brain merekrut 30 orang pada fase akut dan mengacak mereka. Sesi berbantuan berlangsung tiga kali seminggu selama delapan minggu. Ukuran spastisitas juga dikumpulkan.",
        result="Artikel melaporkan perbaikan yang lebih besar pada kelompok berbantuan di Nine-Hole Peg Test, kuesioner ABILHAND, dan indeks Barthel. Itu temuan antarkelompok pada sampel ini. Bukan kecepatan pemulihan yang dijanjikan. Spastisitas tidak menunjukkan perbedaan antarkelompok yang bermakna, jadi tidak setiap ukuran terpisah.",
        sig=[
            "Bagian yang berguna adalah waktunya: latihan berbantuan diuji pada fase akut terhadap terapi neurodevelopmental yang sedang berjalan, bukan dipinjam dari hasil fase kronik. Tiga ukuran fungsi yang bergerak bersama lebih informatif daripada satu skor.",
            "Tiga puluh pasien yang diacak hanya menopang pembacaan yang hati-hati. Uji ini tidak menjawab pemakaian jangka panjang di rumah, dan tidak menunjukkan bahwa setiap subtipe stroke mengikuti jalur yang sama. Klinisi yang merawat tetap menetapkan rencana.",
        ],
        limit="Sampel kecil (n=30). Tidak ada perbedaan antarkelompok yang bermakna pada spastisitas. Perubahan skor adalah laporan studi, bukan janji perorangan.")

    add(2, "id",
        title="Fungsi tangan pascastroke: RCT tersamar tunggal sarung tangan robotik lunak dan terapi cermin, dengan tindak lanjut 6 bulan",
        desc="Journal of Rehabilitation Medicine, 2025: 49 peserta, sarung tangan robotik lunak versus terapi cermin, delapan minggu plus tindak lanjut enam bulan. Nilai P antarkelompok adalah laporan artikel.",
        lead="Terapi cermin memakai masukan visual untuk mengajak sisi yang terkena. Sarung tangan robotik lunak memakai aktuator yang lentur untuk mengulang membuka dan menutup. Perubahan mana yang lebih lama tidak dapat dijawab pada hari latihan terakhir. Uji acak tersamar tunggal tahun 2025 di Journal of Rehabilitation Medicine membandingkan kedua cara selama delapan minggu dan mengikuti orang hingga enam bulan. Artikel melaporkan peningkatan antarkelompok yang bermakna secara statistik untuk sarung tangan pada Box and Block Test, kekuatan genggam, dan FMA-UE di akhir latihan, serta bahwa peningkatan kelompok sarung tangan itu masih ada pada enam bulan.",
        bg=[
            "Pertanyaan yang penting setelah latihan tangan adalah apakah perubahan masih ada setelah orang pulang. Terapi cermin sederhana dan bergantung pada perhatian ke tungkai yang dipantulkan. Sarung tangan memindahkan pengulangan ke aktuator luar, dengan tuntutan perhatian dan daya tahan yang berbeda. Keduanya metode rehabilitasi. Ini bukan peringkat merek.",
            "Skor pada hari latihan terakhir dapat mencampur rangsang singkat dengan perubahan yang stabil. Perbandingan acak dengan kunjungan enam bulan membuat pembedaan itu mungkin.",
        ],
        device="Foto rubrik menunjukkan susunan latihan cermin E12. Alat studi adalah apa yang artikel sebutkan; foto bukan padanan model.",
        design="Pengacakan tersamar tunggal sarung tangan robotik lunak terhadap terapi cermin. Luaran adalah ketangkasan menggenggam dan melepas (Box and Block), kekuatan genggam, dan gerakan lengan atas (FMA-UE), dengan kunjungan enam bulan setelah latihan.",
        sample="Empat puluh sembilan orang pascastroke diacak. Latihan berlangsung delapan minggu. Registrinya NCT05898971.",
        result="Di akhir latihan artikel melaporkan perbedaan antarkelompok yang menguntungkan sarung tangan: Box and Block P=0,004, genggam P=0,011, FMA-UE P=0,021. Pada enam bulan peningkatan kelompok sarung tangan masih ada. Nilai P itu menggambarkan sampel ini. Nilai itu tidak menetapkan besar pemulihan bagi setiap pasien.",
        sig=[
            "Informasi tambahannya adalah waktu. Perbedaan antarkelompok belum hilang pada kunjungan tindak lanjut. Itu lebih berguna secara klinis daripada peringkat pada hari latihan terakhir.",
            "Empat puluh sembilan orang tetap uji yang kecil. Perbedaan awal, sisi lesi, dan latihan setelah pulang semuanya dapat menggeser skor enam bulan. Temuan ini milik populasi ini dan kontras ini.",
        ],
        limit="Sampel kecil (n=49). Nilai P dan peningkatan yang bertahan adalah laporan studi, bukan janji produk.")

    add(3, "id",
        title="Neglect unilateral pada stroke subakut: perbandingan acak latihan cermin robotik pada SY-HRE12",
        desc="NeuroRehabilitation, 2025: 24 orang pada fase subakut, semuanya memakai SY-HRE12. Mode cermin versus gerak pasif yang diatur, 30 menit, tiga kali seminggu, lima minggu.",
        lead="Sebagian orang pada fase subakut memiliki lebih dari tangan yang lemah. Mereka juga dapat mengabaikan satu sisi ruang, dan suasana hati dapat ikut terbebani. Latihan cermin robotik memetakan tangan yang kurang terkena ke tangan yang terkena, sehingga penglihatan dan gerakan tiba dalam pengulangan yang sama. Uji acak tahun 2025 di NeuroRehabilitation membandingkan dua cara memakai sarung tangan lunak yang sama: fungsi cermin, dan mode pasif yang diatur. Artikel melaporkan keunggulan latihan cermin pada luaran yang terkait neglect dan depresi. Sampelnya 24 orang.",
        bg=[
            "Neglect membuat skor sulit dibaca. Masalahnya bukan hanya tangan tidak terangkat; perhatian ke satu sisi ruang berkurang. Cermin biasa dapat memberi kesan tangan yang terkena bergerak padahal tidak. Cermin robotik mencoba membuat sarung tangan yang terkena bergerak bersama tangan yang lain, sehingga melihat dan melakukan mengisi percobaan yang sama.",
            "Jika kelompok memakai alat yang berbeda, setiap perbedaan bisa berasal dari perangkat keras. Uji ini memberi kedua kelompok SY-HRE12 dan hanya mengubah modenya. Pertanyaannya adalah bagaimana sarung tangan digerakkan, bukan apakah ada mesin baru.",
        ],
        device="Artikel memakai SYREBO SY-HRE12. Foto menunjukkan konsol E12, sarung tangan berdaya, dan sarung tangan cermin agar sistem dikenali. Alat studi adalah SY-HRE12.",
        design="Perbandingan acak. Kedua kelompok memakai SY-HRE12. Satu kelompok memakai fungsi cermin. Yang lain memakai gerak pasif yang diatur. Luaran mencakup neglect unilateral, ukuran terkait depresi, dan aktivitas harian.",
        sample="Dua puluh empat orang pada fase subakut, 12 di tiap kelompok. Sesi berlangsung 30 menit, tiga kali seminggu, selama lima minggu.",
        result="Pada sampel ini artikel melaporkan keunggulan latihan cermin robotik atas gerak pasif yang diatur pada luaran terkait neglect dan depresi. Itu perbedaan antara dua mode satu alat. Itu tidak berarti sarung tangan mengobati neglect atau depresi. Kondisi kontrol bukan kotak cermin biasa.",
        sig=[
            "Pertanyaannya bergeser dari «apakah memakai sarung tangan» ke «mode mana dari sarung tangan yang sama». Bagi orang yang juga memiliki neglect dan beban suasana hati, itu pertanyaan klinis yang lebih tepat.",
            "Dua puluh empat peserta hanya menopang pembacaan yang hati-hati. Uji ini tidak menguji pemakaian di rumah tanpa pengawasan, dan tidak menjanjikan perubahan perhatian atau suasana hati.",
        ],
        limit="Sampel kecil (12 per kelompok). Mode kontrol adalah gerak pasif yang diatur, bukan kotak cermin. Perbedaan adalah laporan studi.")

    add(4, "id",
        title="Genggaman dan skor motorik setelah stroke: uji acak sarung tangan latihan robotik",
        desc="SPORT TK, 2025: 30 peserta. Selisih rerata yang dilaporkan: genggam 1,87 (95% CI 0,39–3,35, P=0,015) dan Fugl-Meyer 16,67 (95% CI 3,9–29,4, P=0,012). Tidak ada model yang disebut.",
        lead="Setelah stroke, klinisi sering membagi tangan menjadi dua masalah praktis: apakah ia dapat menggenggam, dan apakah ia dapat bergerak terkendali. Uji acak tahun 2025 di SPORT TK-EuroAmerican Journal of Sport Sciences mengukur keduanya. Artikel melaporkan selisih rerata antarkelompok yang bermakna secara statistik, menguntungkan sarung tangan latihan robotik, pada genggaman dan pada skor motorik Fugl-Meyer. Tiga puluh orang ikut serta, dan artikel tidak menyebut model komersial.",
        bg=[
            "Perubahan genggaman tidak harus menghasilkan gerakan yang dapat dipakai, dan skor motorik yang lebih tinggi tidak berarti seseorang dapat mengangkat cangkir. Mengukur gaya dan gerakan dalam perbandingan acak yang sama menghindari penerbitan hanya yang lebih ramah dari keduanya.",
            "Artikel tentang sarung tangan sering menghilangkan model. Tanpa model, hasil tidak dapat disalin ke spesifikasi produk. Ringkasan ini karena itu tetap pada kontras yang benar-benar diberikan artikel.",
        ],
        device="",
        design="Perbandingan acak latihan dengan sarung tangan latihan robotik terhadap kondisi kontrol. Luaran bersama adalah genggaman dan skor motorik Fugl-Meyer, dilaporkan sebagai selisih rerata dengan interval kepercayaan 95%.",
        sample="Tiga puluh orang pascastroke, 15 di tiap kelompok. Artikel tidak mengidentifikasi model yang dipasarkan. Foto sarung tangan generik adalah ilustrasi, bukan identifikasi alat.",
        result="Selisih rerata antarkelompok yang dilaporkan adalah genggam 1,87 (95% CI 0,39 hingga 3,35, P=0,015) dan Fugl-Meyer 16,67 (95% CI 3,9 hingga 29,4, P=0,012). Selisih rerata bukan peningkatan tiap orang. Interval skor motorik lebar, dan itulah rupa sampel kecil ketika estimasinya tidak presisi.",
        sig=[
            "Menerbitkan selisih sekaligus interval lebih dapat dipakai daripada kalimat «lebih baik daripada kontrol». Arahnya terlihat, begitu pula ketidakpastiannya.",
            "Karena tidak ada model yang disebut, hasil tidak dapat diceritakan ulang sebagai spesifikasi atau indikasi sarung tangan Syrebo tertentu. Tiga puluh orang juga menyisakan ruang bagi derau sampling.",
        ],
        limit="Sampel kecil (n=30). Tidak ada model yang diidentifikasi, dan foto bukan padanan. Selisih rerata dan nilai P adalah statistik studi.")

    add(5, "id",
        title="Fungsi tangan pada fase subakut dini: RCT pilot tersamar tunggal SY-HR03E dari tim Huashan",
        desc="RCT pilot tersamar tunggal di BioMedical Engineering OnLine: 20 pasien rawat inap, SY-HR03E, empat minggu. Artikel melaporkan penyelesaian penuh, tidak ada kejadian tidak diinginkan, dan sinyal awal pada skor tangan serta aktivitas harian.",
        lead="Pada fase subakut dini pertanyaan pertama bukan berapa poin skor dapat naik. Pertanyaannya apakah sesi dapat diselesaikan, dan apakah sesi itu aman. Tim yang dipimpin Profesor Jia Jie di Rumah Sakit Huashan, Universitas Fudan, menerbitkan di BioMedical Engineering OnLine uji acak pilot tersamar tunggal tentang Syrebo SY-HR03E untuk rehabilitasi tangan pada jendela itu. Artikel melaporkan bahwa ke-20 peserta menyelesaikan empat minggu, tanpa putus dan tanpa kejadian tidak diinginkan. Skor tangan membaik di kedua kelompok, dengan perubahan yang lebih besar pada kelompok sarung tangan. Perubahan dalam kelompok pada aktivitas harian mencapai kemaknaan statistik pada kelompok sarung tangan.",
        bg=[
            "Lengan dan tangan biasanya pulih lebih lambat daripada berjalan. Makan, berpakaian, dan mencuci bergantung pada gerakan jari yang terpisah, bukan pada satu angka kekuatan. Terapi tangan biasa membantu, tetapi jumlah pengulangan yang dapat diberikan terapis terbatas, dan gerakan yang sama sulit diulang di sisi tempat tidur.",
            "Sarung tangan pneumatik dapat menekuk dan meluruskan jari dengan massa yang kecil di tangan, dan karena itu pemakaian di sisi tempat tidur dibicarakan. Orang pada fase subakut dini juga pulih secara spontan. Setiap «efek awal» harus dibaca dengan latar itu. Uji acak pilot ada untuk menunjukkan bahwa protokol layak dan untuk meninggalkan sinyal bagi studi yang lebih besar. Uji itu tidak menggantikan uji konfirmasi.",
        ],
        device="Artikel menggambarkan SY-HR03E sebagai sarung tangan lunak komersial plus pengendali meja. Massa yang dilaporkan sekitar 3,5 kg untuk sistem dan sekitar 110 g untuk sarung tangan. Bellow pneumatik di punggung tangan membantu fleksi dan ekstensi. Sensor tekanan mengamati perubahan saat orang mencoba bergerak; di atas ambang yang diatur 0,7 kPa pengendali memperlakukan perubahan itu sebagai niat gerak dan mengembang atau mengempis. Mode yang dimaksud adalah bantuan aktif, bukan tarikan yang sepenuhnya pasif.",
        design="Pengacakan pilot tersamar tunggal. Kelompok robotik menambahkan buka-tutup berbantuan sarung tangan pada rehabilitasi standar. Kelompok biasa menerima terapi tangan tradisional dengan lama sesi yang sama. Kedua kelompok juga menerima satu jam sehari rehabilitasi standar. Terapis mengawasi postur. Registri: ChiCTR2000034614.",
        sample="Dua puluh pasien rawat inap, 7 hari hingga 3 bulan setelah onset, 10 di tiap kelompok. Sesi sarung tangan 30 menit sehari, lima hari seminggu, selama empat minggu. Setiap buka-tutup ditahan sekitar tiga detik. Afiliasi penulis mencakup tim klinis dan, seperti yang diungkapkan artikel, Shanghai Siyi Intelligent Technology. Hubungan itu bagian dari pembacaan.",
        result="Artikel melaporkan bahwa ke-20 orang menyelesaikan empat minggu, tanpa putus dan tanpa kejadian tidak diinginkan. Skor Fugl-Meyer tangan membaik di kedua kelompok, dengan perbaikan yang lebih besar pada kelompok robotik. Pada indeks Barthel yang dimodifikasi, hanya perubahan dalam kelompok robotik yang dilaporkan bermakna secara statistik (p<0,001); perubahan dalam kelompok biasa tidak. Stadium Brunnstrom tangan juga menunjukkan perubahan dalam kelompok yang bermakna hanya pada kelompok robotik. Pada pilot 10 lawan 10, nilai P dalam kelompok adalah sinyal, bukan bukti bahwa fungsi harian akan naik bagi pasien pada umumnya.",
        sig=[
            "Banyak studi sarung tangan lunak merekrut orang pada fase kronik. Pilot ini memindahkan pertanyaan kelayakan dan keamanan ke jendela 7 hari hingga 3 bulan. Pilot ini tidak memajukan klaim khasiat fase kronik.",
            "Skor tangan dan skor aktivitas harian tidak mengambil bentuk statistik yang sama: artikel melaporkan perubahan Barthel dalam kelompok yang bermakna hanya pada kelompok sarung tangan. Pemisahan itu layak diuji lagi. Itu bukan pernyataan bahwa aktivitas hidup sehari-hari telah selesai. Sarung tangan 110 g dan deteksi niat membuat pembicaraan di sisi tempat tidur, dan kemudian di rumah, mungkin. Studi ini sendiri dilakukan pada pasien rawat inap.",
        ],
        limit="Pengacakan pilot, 10 per kelompok. Sinyal awal membutuhkan sampel yang lebih besar. Nilai P adalah laporan artikel untuk luaran itu. Afiliasi yang terkait alat diungkapkan dan harus dipertimbangkan.")

    add(6, "id",
        title="Gangguan tangan dengan pola stasis dahak: studi empat lengan 200 orang tentang sarung tangan plus elektroakupunktur",
        desc="Journal of Hunan University of Chinese Medicine: 200 peserta, empat lengan. Angka efektivitas total yang dilaporkan 88%, 76%, 77,6%, dan 70,8%. Angka itu komposit studi, bukan angka produk.",
        lead="Menempatkan sarung tangan robotik dan elektroakupunktur dalam satu rencana adalah pilihan integratif yang spesifik, dan hasilnya harus tetap melekat pada lengan yang menghasilkannya. Studi empat lengan tahun 2022 di Journal of Hunan University of Chinese Medicine merekrut 200 orang dengan gangguan tangan pascastroke berpola phlegm-stasis blocking collaterals dan membandingkan sarung tangan plus elektroakupunktur, sarung tangan saja, elektroakupunktur saja, dan rehabilitasi biasa. «Angka efektivitas total» milik artikel adalah 88%, 76%, 77,6%, dan 70,8%. Komposit itu ringkasan para penulis. Bukan angka khasiat produk.",
        bg=[
            "Di bawah diagnosis pola ini, jalur sering menggabungkan rehabilitasi modern dengan elektroakupunktur. Tata letak empat lengan dapat menunjukkan kombinasi, alat saja, akupunktur saja, dan perawatan biasa pada satu skala, alih-alih cerita sebelum-sesudah tanpa kontras.",
            "Angka efektivitas total meruntuhkan beberapa penilaian menjadi satu persentase. Berguna untuk kontras kasar dan tidak berguna sebagai perubahan seseorang pada skala yang bernama. Tidak dapat dikutip sebagai «khasiat sarung tangan adalah 88%».",
        ],
        device="",
        design="Empat lengan: sarung tangan robotik plus elektroakupunktur, sarung tangan saja, elektroakupunktur saja, dan rehabilitasi biasa. Luaran yang dibahas di sini adalah angka efektivitas total artikel. Afiliasi mencakup Shanghai Siyi Intelligent Technology, dengan Yin Ganggang sebagai penulis pendamping. Pengungkapan itu tetap dalam pembacaan.",
        sample="Dua ratus orang dengan gangguan tangan pascastroke berpola phlegm-stasis blocking collaterals. Ini sampel terbesar di rubrik. Artikel tidak menyebut model yang dapat dicocokkan dengan produk saat ini, dan foto generik bukan padanan itu.",
        result="Angka efektivitas total yang dilaporkan adalah 88% untuk sarung tangan plus elektroakupunktur, 76% untuk sarung tangan saja, 77,6% untuk elektroakupunktur saja, dan 70,8% untuk rehabilitasi biasa. Komposit yang lebih tinggi pada lengan gabungan hanya berarti, menurut aturan studi ini, lengan itu mencetak lebih tinggi. Angka itu tidak menempatkan 88% pada sarung tangan, dan 76% bukan angka produk. Angka sarung tangan saja dan elektroakupunktur saja berdekatan, yang juga menentang penjelasan seluruh pola oleh satu komponen.",
        sig=[
            "Dua ratus orang dan empat lengan memberi komposit yang dapat dibandingkan, bukan persentase untuk halaman produk. Dibaca sebagai angka efektivitas total, jarak antara kombinasi, modalitas tunggal, dan perawatan biasa terbatas.",
            "Artikel, sebagaimana diringkas di sini, tidak memasok selisih rerata yang sama dengan uji lain di rubrik. Sampai skala itu ada di meja, studi ini tentang bagaimana komponen digabung, bukan tentang berapa poin skor tangan akan naik.",
        ],
        limit="Persentase adalah angka efektivitas total milik studi. Lengan gabungan tidak dapat diatribusikan pada sarung tangan atau elektroakupunktur saja. Tidak ada model yang disebut.")

    add(7, "id",
        title="Rehabilitasi tangan setelah infark arteri serebri media: laporan kasus seorang pasien berusia 66 tahun",
        desc="Laporan kasus Cureus: perempuan 66 tahun dengan infark bilateral wilayah ACM menerima program sarung tangan Syrebo di bawah pengawasan klinis. Satu kasus bukan hasil umum.",
        lead="Uji acak menggambarkan perbedaan rata-rata. Laporan kasus menggambarkan bagaimana rehabilitasi diatur untuk satu orang. Pada 2024 di Cureus, Sharma dan rekan melaporkan perempuan 66 tahun dengan infark di wilayah arteri serebri media yang menerima neurofisioterapi yang dibangun di sekitar program sarung tangan Syrebo. Laporan mengikuti jalannya pengamatan dan perubahan fungsi. Ini satu kasus, dan tidak digeneralisasi.",
        bg=[
            "Infark di wilayah ini sering mengenai lengan dan tangan bersama bahasa atau kognisi, jadi rencananya lebih dari tangan yang lemah. Keluarga biasanya perlu tahu kapan latihan sarung tangan berada di dalam fisioterapi, dan siapa yang mengawasi, lebih daripada sebuah persentase.",
            "Laporan kasus dapat menuliskan urutan itu. Tidak ada kontrol sejajar, jadi setiap perubahan sebelum-sesudah mencampur pemulihan spontan, perawatan biasa, dan sarung tangan. Bagian-bagian itu tidak dapat dipisah.",
        ],
        device="Artikel membahas program sarung tangan Syrebo dan tidak menyebut model. Foto sarung tangan dan konsol adalah Gambar 2 laporan akses terbuka itu (CC BY 4.0), ditunjukkan pada kutipan di atas. Bukan gambar dari tinjauan lain.",
        design="Laporan satu kasus, bukan uji acak. Setelah orang itu stabil secara medis, klinisi memberi neurofisioterapi yang mencakup program sarung tangan Syrebo.",
        sample="Perempuan 66 tahun dengan infark bilateral wilayah ACM. Laporan mencatat pengamatan dan perubahan fungsi. Tidak menyediakan statistik antarkelompok.",
        result="Nilai laporan adalah jalannya perawatan, bukan angka perbaikan. Laporan menunjukkan bagaimana sarung tangan lunak ditempatkan di dalam rehabilitasi satu orang dengan infark berat, di bawah pengawasan profesional. Perubahan pada satu kasus bukan derajat pemulihan yang dijanjikan.",
        sig=[
            "Di rubrik yang sebagian besar uji acak, satu laporan kasus ada di sini untuk menunjukkan bagaimana program dipakai pada seseorang. Ia mengisi celah naratif. Ia tidak menaikkan tingkat bukti.",
            "Satu kasus tidak dapat memperkirakan seberapa sering kejadian tidak diinginkan terjadi, dan tidak dapat mengatakan apakah fase akut, subakut, atau kronik yang lebih cocok. Pertanyaan itu tetap pada studi terkontrol.",
        ],
        limit="Kasus tunggal. Bukan efek umum. Perubahan fungsi tidak dapat dibebankan pada sarung tangan saja.")

    add(8, "id",
        title="Gangguan lengan atas setelah stroke: studi acak 60 orang tentang terapi cermin inovatif",
        desc="New Medicine, 2024: 60 orang, empat minggu. Artikel melaporkan peningkatan yang lebih besar pada FMA-UE, FMA-WH, dan indeks Barthel yang dimodifikasi dengan terapi cermin inovatif dibanding terapi cermin biasa.",
        lead="Terapi cermin biasa memakai cermin untuk memberi kesan bahwa tangan yang terkena bergerak. Versi inovatif meminta sarung tangan robotik membawa tangan yang terkena melalui tindakan yang sama yang ditunjukkan cermin, sehingga melihat dan melakukan berbagi sesi. Pada 2024 New Medicine menerbitkan studi acak Chen dan rekan yang membandingkan kedua versi pada 60 orang selama empat minggu. Artikel melaporkan peningkatan yang lebih besar untuk terapi cermin inovatif pada gerakan lengan atas, gerakan pergelangan-tangan, dan aktivitas harian.",
        bg=[
            "Terapi cermin punya batas yang dikenal: jika tangan yang terkena tidak bergerak, saran visual tidak punya masukan motorik yang berpasangan. Menghubungkan fleksi dan ekstensi berbantuan ke tugas cermin adalah upaya agar sisi yang terkena benar-benar menyelesaikan gerakan di dalam rentang yang ditetapkan terapis.",
            "Apakah perubahan itu muncul pada skor harus diuji terhadap terapi cermin biasa, bukan terhadap tidak melakukan apa-apa. Enam puluh orang, dibagi rata, adalah ukuran acak yang awal.",
        ],
        device="Gambar latihan di halaman jurnal menunjukkan tanda Yisheng (羿生). Rubrik memetakan tanda itu ke SY-HR08E pada bahan resmi dan menunjukkan foto produk dengan layar, konsol, dan sarung tangan. Pemetaan itu catatan identifikasi, bukan klaim model yang dicetak sebagai registrasi uji.",
        design="Alokasi dengan angka acak. Terapi cermin inovatif, yang menggabungkan tugas cermin dengan sarung tangan robotik, dibandingkan dengan terapi cermin biasa. Luaran mencakup FMA-UE, FMA-WH, dan indeks Barthel yang dimodifikasi.",
        sample="Enam puluh orang dengan gangguan lengan atas pascastroke, 30 di tiap kelompok, selama empat minggu.",
        result="Artikel melaporkan perbaikan yang lebih besar untuk terapi cermin inovatif pada FMA-UE, FMA-WH, dan indeks Barthel yang dimodifikasi. Itu deskripsi antarkelompok studi. Rerata dan nilai P tidak dihitung ulang di halaman ini; selama halaman jurnal masih diperiksa, angka itu tetap pada artikel.",
        sig=[
            "Pertanyaannya apakah menambahkan gerakan berbantuan yang sesuai cermin mengubah skor relatif terhadap cermin saja. Enam puluh orang memberi kontras awal, bukan bukti program rumah.",
            "Mengaitkan gambar jurnal dengan SY-HR08E hanya membantu pembaca mengenali alat. Apakah perbedaan skor stabil menunggu pemeriksaan independen atas angka lengkap.",
        ],
        limit="Tiga puluh orang per kelompok. Perbedaan mengikuti artikel. Rerata dan nilai P tidak dihitung ulang di sini. Kaitan model adalah pemeriksaan antara gambar jurnal dan bahan resmi.")

    add(9, "id",
        title="Hemiparesis kiri setelah infark ACM: satu catatan stimulasi faradik plus tangan robotik",
        desc="Kasus IJPRCP: laki-laki 60 tahun dengan hemiparesis kiri memulai stimulasi faradik plus Syrebo C12 sekitar tiga bulan setelah stroke, lima kali seminggu selama empat minggu. Satu kasus gabungan tidak dibebankan pada salah satu komponen.",
        lead="Tangan hemiparetik kadang diberi dua masukan sekaligus: stimulasi listrik yang diarahkan ke otot, dan tangan robotik untuk membuka serta menutup jari. Laporan kasus tahun 2025 di International Journal of Physiotherapy Research and Clinical Practice mencatat empat minggu stimulasi faradik plus Syrebo C12 pada seorang laki-laki dengan hemiparesis kiri. Ini catatan rencana gabungan, bukan uji khasiat salah satu bagian.",
        bg=[
            "Beberapa bulan setelah stroke, perubahan tangan biasanya lebih lambat, dan klinisi kadang menambahkan stimulasi atau bantuan luar pada latihan biasa. Begitu keduanya dipakai, perubahan sebelum-sesudah tidak dapat diberikan secara bersih kepada salah satu.",
            "Laporan itu tetap berguna. Ia menyatakan kapan rencana dimulai, seberapa sering berjalan, dan alat mana yang ada di ruangan. Ia tidak memberi angka, dan tidak memberi perbedaan terhadap kontrol.",
        ],
        device="Alat robotik dalam laporan adalah Syrebo C12. Foto adalah potongan dari halaman produk resmi C12 agar konsol dan sarung tangan dikenali. Foto tidak menambah spesifikasi yang dihilangkan artikel.",
        design="Satu intervensi gabungan: stimulasi faradik bersama latihan tangan robotik Syrebo C12. Tidak ada kelompok kontrol sejajar.",
        sample="Laki-laki 60 tahun dengan hemiparesis kiri. Rencana dimulai 3 bulan 2 minggu setelah stroke, lima kali seminggu, selama empat minggu.",
        result="Halaman ini tidak mencetak ulang skor fungsi yang belum diperiksa terhadap artikel untuk rubrik. Yang jelas adalah susunannya: stimulasi dan latihan robotik dipakai bersama, jadi perubahan tidak dapat ditulis sebagai efek C12 saja atau stimulasi saja.",
        sig=[
            "Catatan ini menambah jadwal yang konkret: sekitar tiga bulan setelah stroke, lima sesi seminggu, dua modalitas bersama. Ia tidak menaikkan tingkat bukti.",
            "Satu kasus hemiparesis kiri setelah infark ACM tidak mewakili lesi lain atau waktu lain setelah onset.",
        ],
        limit="Kasus gabungan tunggal. Perubahan tidak dibebankan pada C12 atau stimulasi, dan bukan efek umum.")

    add(10, "id",
        title="Ortesis pergelangan-tangan yang lunak: rancangan dan evaluasi awal di Wearable Technologies",
        desc="Ledoux dan Barth melaporkan ortesis pergelangan-tangan cetak 3D milik mereka di Wearable Technologies. Catatan ini tetap pada artikel rancangan itu. Tidak memeringkat produk komersial dan bukan uji khasiat.",
        lead="Pada 2024 Wearable Technologies, dari Cambridge University Press, menerbitkan artikel rancangan Ledoux dan Barth di Universitas Vanderbilt. Alat yang mereka bangun dan evaluasi secara awal adalah ortesis genggam pergelangan-tangan cetak 3D milik mereka sendiri. Artikel menyebut struktur lunak komersial saat membahas tangan yang dapat dikenakan. Rubrik ini tidak mengubah pembahasan itu menjadi peringkat, dan tidak memperlakukan artikel sebagai bukti khasiat Syrebo.",
        bg=[
            "Alat tangan yang meninggalkan ruang terapi harus menjawab berat, profil, dan apakah seseorang dapat memakainya. Artikel rancangan biasanya menyatakan batasan itu lalu menggambarkan prototipe. Mereka tidak lebih dulu melaporkan uji fungsi multisentra. Membaca artikel rancangan sebagai artikel khasiat mengarang luaran klinis yang tidak diukur.",
            "Struktur lunak dan eksoskeleton kaku menjawab masalah rekayasa yang berbeda. Kelunakan adalah satu cara mengurangi profil. Berbicara tentang perubahan fungsi tetap membutuhkan studi manusia tersendiri.",
        ],
        device="Kutipan di atas adalah halaman pertama akses terbuka (CC BY 4.0), bukan tabel perbandingan. Foto produk menunjukkan sistem sarung tangan klinis Syrebo. Bukan gambar dari percobaan ini.",
        design="Rancangan, pemodelan, dan evaluasi awal atas ortesis cetak 3D milik para penulis sendiri. Artikel bukan uji acak Syrebo dan bukan perbandingan khasiat antaralat yang dipasarkan.",
        sample="Bagian manusia adalah tinjauan awal atas prototipe para penulis. Ukuran dan tugasnya adalah milik artikel. Tidak ditulis ulang di sini sebagai kohort Syrebo.",
        result="Halaman ini tidak mengutip kata sifat komersial dan tidak mendaftar merek lain. Yang tersisa adalah bahwa artikel ini studi rancangan akses terbuka tentang struktur yang lunak dan dapat dikenakan. Kata para penulis «presumably» menandai kenyamanan sebagai sesuatu yang tidak mereka perlakukan sebagai luaran yang diukur.",
        sig=[
            "Artikel ada di rubrik agar studi rancangan tetap berbeda dari uji khasiat. Apakah struktur lunak membuat alat lebih mudah dipakai dalam kehidupan sehari-hari adalah studi pemakaian dan studi fungsi, secara terpisah.",
            "Akses terbuka memungkinkan pembaca memeriksa rumusan. Maksud pemeriksaan adalah menjaga anggapan agar tidak menjadi kesimpulan, bukan memilih produk yang paling ringan.",
        ],
        limit="Bukan uji khasiat Syrebo, dan bukan peringkat produk. Sumber memagari kenyamanan dengan «presumably». Potongan halaman pertama tidak memuat tabel perbandingan.")

    add(11, "id",
        title="Robot jari yang ditujukan untuk rumah: catatan pengembangan di Journal of the Robotics Society of Japan",
        desc="Artikel 2023 di Journal of the Robotics Society of Japan membahas robot jari untuk pemakaian di rumah pada hemiparesis dan menyebut Syrebo di antara sedikit contoh yang dikomersialkan. Bukan uji klinis.",
        lead="Rehabilitasi tangan di rumah telah dibahas bertahun-tahun. Contoh yang dikomersialkan dalam literatur perkumpulan masih sedikit. Pada 2023 Journal of the Robotics Society of Japan menerbitkan artikel Furudate dan rekan tentang robot rehabilitasi jari yang ditujukan untuk pemakaian di rumah setelah hemiparesis, dan tentang mengembangkannya bersama klinisi. Para penulis mencatat bahwa kasus pemakaian di rumah yang dikomersialkan tetap jarang, dan mereka menyebut sarung tangan Syrebo sebagai salah satu kasus itu. Artikel ini catatan pengembangan dan kolaborasi, bukan uji khasiat.",
        bg=[
            "Di antara bangsal dan rumah terdapat cara memakai, batas keamanan, dan pemakaian ketika tidak ada terapis di ruangan. Artikel rekayasa menempatkan batasan itu di dalam kerja bersama klinisi. Disebut berarti para penulis memilih produk ini sebagai contoh. Bukan berarti perkumpulan menjalankan studi terkontrol.",
            "«Sedikit yang dikomersialkan» juga sebuah batas. Membacanya sebagai «rehabilitasi di rumah sudah tersedia secara umum» mengubah contoh menjadi klaim epidemiologis.",
        ],
        device="Artikel tidak mencetak foto sarung tangan. Gambar sarung tangan dan konsol di rubrik ini adalah Gambar 2 laporan kasus Cureus 2024 oleh Sharma dan rekan (CC BY 4.0). Keterangan mengatakannya. Bukan gambar asli artikel perkumpulan Jepang.",
        design="Artikel pengembangan di jurnal perkumpulan tentang robot jari untuk pemakaian di rumah dan tentang bekerja bersama klinisi. Tidak ada pengacakan dan tidak ada perbandingan fungsi antarkelompok.",
        sample="Ukuran sampel klinis tidak berlaku. Artikel membahas jalan menuju produk, bukan luaran pada suatu kohort.",
        result="Pernyataan, sebagaimana dipakai di sini, adalah bahwa robot jari yang dikomersialkan dan ditujukan ke rumah masih sedikit, dan bahwa Syrebo adalah satu contoh yang disebut para penulis. Rubrik menjaga lingkup itu. Tidak ditulis ulang sebagai khasiat, peringkat pasar, atau janji bahwa latihan di rumah akan diselesaikan.",
        sig=[
            "Nilai catatan ini adalah bahwa pemakaian di rumah diperlakukan sebagai masalah rekayasa yang ditetapkan bersama klinisi. Contoh yang dikomersialkan menunjukkan bahwa satu alat berpindah dari prototipe ke produk.",
            "Apakah alat itu dapat dipakai dengan aman dan berulang di rumah tetap bergantung pada indikasi, pengawasan, dan studi klinis yang terpisah. Artikel perkumpulan tidak menyediakan data itu.",
        ],
        limit="Bukan uji klinis Syrebo. Sumber menekankan bahwa contoh yang dikomersialkan tetap sedikit. Foto berasal dari laporan kasus akses terbuka yang lain.")

    # ----- Korean -----------------------------------------------------------
    add(1, "ko",
        title="급성기 뇌졸중의 손 기능: NP Brain 병원의 로봇 보조 훈련 무작위 연구",
        desc="NP Brain 병원 30명 무작위 연구. 로봇 보조 손 훈련이 신경발달 치료에 더해졌다. Nine-Hole Peg, ABILHAND, Barthel 결과는 연구의 보고다.",
        lead="뇌졸중 뒤 손은 걷기보다 일상 동작으로 늦게 돌아오는 일이 많다. 컵, 단추, 식기가 구체적인 장애가 된다. 급성기 창은 빨리 변하므로, 그 안에 더하는 것은 한 사례의 인상이 아니라 무작위 비교로 재야 한다. 2026년 Scientific Reports는 튀르키예 NP Brain 병원의 무작위 연구를 실었다. 통상적인 신경발달 치료에 Syrebo 로봇 보조 손 훈련을 더한 연구다. 논문은 치료만 받은 쪽보다 기민성, 양손 활동, 자기관리에서 더 큰 향상을 보고한다. 표본은 30명이며, 경직은 집단을 가르지 않았다.",
        bg=[
            "손은 힘, 분절된 움직임, 실제 사용을 함께 요구해서 어렵다. 보행은 하나의 목표로 연습할 수 있지만, 손은 불안정한 자세 안에서 쥐고 놓아야 한다. 신경발달 치료는 이미 급성기 재활의 바탕이다. 다만 치료사가 모든 잡기를 끝없이 반복할 수는 없어 용량과 일관성을 늘리기 어렵다.",
            "소프트 로봇 장갑은 원칙적으로 감독 아래 그 반복을 공급할 수 있다. 급성기 환자는 아직 변하고 있다. 기기를 안전하게 더할 수 있는지, 기능 점수가 함께 움직이는지는 대조가 있는 질문이다. 이 연구는 만성기 연구를 반복하는 대신 그 시기를 다룬다.",
        ],
        device="논문은 기기를 SYREBO 로봇 손으로 적는다. 사진은 형태를 보이려 소프트 장갑, 본체, 태블릿을 보여 준다. 모델의 세부 사항은 논문과 임상 계획에 속한다.",
        design="단일 기관 무작위 비교. 한 집단은 로봇 보조 손 훈련에 신경발달 치료(NT)를 더했다. 대조군은 NT만 받았다. 결과는 근력만이 아니라 미세 기민성, 양손 일상 활동, 자기관리였다.",
        sample="NP Brain 병원은 급성기 30명을 등록하고 무작위 배정했다. 로봇 보조 세션은 주 3회, 8주였다. 경직 측정도 함께 모았다.",
        result="논문은 로봇 보조군에서 Nine-Hole Peg Test, ABILHAND 설문, Barthel 지수의 향상이 더 컸다고 보고한다. 이 표본의 집단 간 소견이다. 약속된 회복 속도가 아니다. 경직은 유의한 집단 간 차이를 보이지 않아, 모든 측정이 벌어진 것은 아니다.",
        sig=[
            "유용한 부분은 시기다. 로봇 보조 연습을 만성기 결과에서 빌려 오지 않고, 진행 중인 신경발달 치료와 대비해 급성기에서 시험했다. 세 기능 측정이 함께 움직이는 것은 점수 하나보다 더 많은 것을 말한다.",
            "무작위 배정 30명은 조심스러운 읽기만 지탱한다. 이 연구는 장기 가정 사용에 답하지 않으며, 모든 뇌졸중 아형이 같은 경로를 따른다고 보여 주지 않는다. 계획은 여전히 담당 임상의가 정한다.",
        ],
        limit="작은 표본(n=30). 경직의 집단 간 유의한 차이 없음. 점수 변화는 연구의 보고이지 개인에 대한 약속이 아니다.")

    add(2, "ko",
        title="뇌졸중 후 손 기능: 소프트 로봇 장갑과 거울 치료의 단일맹검 RCT, 6개월 추적",
        desc="Journal of Rehabilitation Medicine, 2025. 49명, 소프트 로봇 장갑 대 거울 치료, 8주와 6개월 추적. 집단 간 P값은 논문의 보고다.",
        lead="거울 치료는 시각 입력으로 마비측을 불러낸다. 소프트 로봇 장갑은 유연한 구동으로 펴고 쥐기를 반복한다. 어느 변화가 더 오래 가는지는 마지막 훈련일에 답할 수 없다. 2025년 Journal of Rehabilitation Medicine의 단일맹검 무작위 연구는 두 방법을 8주 비교하고 6개월까지 추적했다. 논문은 훈련 종료 시 Box and Block Test, 악력, FMA-UE에서 장갑군에 유리한 통계적으로 유의한 집단 간 향상을 보고하고, 그 장갑군 향상이 6개월에도 남아 있었다고 보고한다.",
        bg=[
            "손 훈련 뒤에 중요한 질문은 집에 돌아간 뒤에도 변화가 있는지다. 거울 치료는 단순하고, 비친 팔다리에 대한 주의에 기대다. 장갑은 반복을 외부 구동으로 옮기며, 주의와 지구력에 대한 요구가 다르다. 둘 다 재활 방법이다. 상표의 순위가 아니다.",
            "마지막 훈련일의 점수는 짧은 자극을 안정된 변화와 섞을 수 있다. 6개월 방문이 있는 무작위 비교가 그 구분을 가능하게 한다.",
        ],
        device="칼럼 사진은 E12 거울 훈련 구성을 보여 준다. 연구 기기는 논문이 적는 것이며, 사진은 모델 일치가 아니다.",
        design="소프트 로봇 장갑과 거울 치료의 단일맹검 무작위 배정. 결과는 쥐고 놓기(Box and Block), 악력, 상지 운동(FMA-UE)이었고, 훈련 6개월 뒤 방문이 있었다.",
        sample="뇌졸중 후 49명이 무작위 배정되었다. 훈련은 8주였다. 등록은 NCT05898971이다.",
        result="훈련 종료 시 논문은 장갑에 유리한 집단 간 차이를 보고한다. Box and Block P=0.004, 악력 P=0.011, FMA-UE P=0.021. 6개월에도 장갑군의 향상은 남아 있었다. 이 P값은 이 표본을 기술한다. 모든 환자에게 회복 크기를 배정하지 않는다.",
        sig=[
            "추가 정보는 시간이다. 집단 간 차이는 추적 방문에서 사라지지 않았다. 마지막 훈련일의 순위보다 임상적으로 더 쓸모 있다.",
            "49명은 여전히 작은 연구다. 기저 차이, 병변 측, 퇴원 후 연습은 모두 6개월 점수를 움직일 수 있다. 소견은 이 집단과 이 대조에 속한다.",
        ],
        limit="작은 표본(n=49). P값과 유지된 향상은 연구의 보고이지 제품의 약속이 아니다.")

    add(3, "ko",
        title="아급성기 편측 무시: SY-HRE12 로봇 거울 훈련의 무작위 비교",
        desc="NeuroRehabilitation, 2025. 아급성기 24명, 모두 SY-HRE12. 거울 모드 대 미리 설정된 수동 운동, 30분, 주 3회, 5주.",
        lead="아급성기의 어떤 사람은 약한 손만 가진 것이 아니다. 공간의 한쪽을 무시할 수 있고, 기분도 함께 흔들릴 수 있다. 로봇 거울 훈련은 덜 마비된 손의 움직임을 마비측에 옮겨, 시각과 운동이 같은 반복 안에 들어오게 한다. 2025년 NeuroRehabilitation의 무작위 연구는 같은 소프트 장갑의 두 사용법을 비교했다. 거울 기능과 미리 설정된 수동 모드다. 논문은 무시 및 우울 관련 결과에서 거울 훈련의 우위를 보고한다. 표본은 24명이다.",
        bg=[
            "무시는 점수를 읽기 어렵게 만든다. 문제가 손이 들리지 않는 것만은 아니다. 공간 한쪽에 대한 주의가 줄어 있다. 일반 거울은 마비된 손이 움직이지 않는데도 움직이는 것처럼 보이게 할 수 있다. 로봇 거울은 마비측 장갑이 다른 손과 함께 움직이게 해, 보는 것과 하는 것이 같은 시행을 차지하게 하려 한다.",
            "집단이 다른 기기를 썼다면 차이는 하드웨어일 수 있다. 이 연구는 양 집단에 SY-HRE12를 주고 모드만 바꿨다. 질문은 새 기계가 있었는지가 아니라 장갑을 어떻게 구동했는지다.",
        ],
        device="논문은 SYREBO SY-HRE12를 썼다. 사진은 시스템을 알아보게 E12 본체, 구동 장갑, 거울 장갑을 보여 준다. 연구 기기는 SY-HRE12다.",
        design="무작위 비교. 양 집단 모두 SY-HRE12를 썼다. 한 집단은 거울 기능을, 다른 집단은 미리 설정된 수동 운동을 썼다. 결과에는 편측 무시, 우울 관련 측정, 일상 활동이 포함되었다.",
        sample="아급성기 24명, 각 집단 12명. 세션은 30분, 주 3회, 5주였다.",
        result="이 표본에서 논문은 무시 및 우울 관련 결과에 대해 미리 설정된 수동 운동보다 로봇 거울 훈련의 우위를 보고한다. 한 기기의 두 모드 차이다. 장갑이 무시나 우울을 치료한다는 뜻이 아니다. 대조 조건은 일반 거울 상자가 아니었다.",
        sig=[
            "질문이 «장갑을 쓸 것인가»에서 «같은 장갑의 어느 모드인가»로 옮겨 간다. 무시와 기분 부담이 함께 있는 사람에게는 더 구체적인 임상 질문이다.",
            "24명은 조심스러운 읽기만 지탱한다. 이 연구는 감독 없는 가정 사용을 시험하지 않으며, 주의나 기분의 보장된 변화를 제시하지 않는다.",
        ],
        limit="작은 표본(집단당 12명). 대조 모드는 미리 설정된 수동 운동이지 거울 상자가 아니다. 차이는 연구의 보고다.")

    add(4, "ko",
        title="뇌졸중 후 악력과 운동 점수: 로봇 훈련 장갑의 무작위 연구",
        desc="SPORT TK, 2025. 30명. 보고된 평균 차: 악력 1.87(95% CI 0.39–3.35, P=0.015), Fugl-Meyer 16.67(95% CI 3.9–29.4, P=0.012). 모델명은 없다.",
        lead="뇌졸중 뒤 임상가는 손을 두 가지 실용 문제로 나누곤 한다. 쥘 수 있는가, 조절하며 움직일 수 있는가. 2025년 SPORT TK-EuroAmerican Journal of Sport Sciences의 무작위 연구는 둘을 함께 측정했다. 논문은 악력과 Fugl-Meyer 운동 점수에서 로봇 훈련 장갑에 유리한, 통계적으로 유의한 집단 간 평균 차를 보고한다. 30명이 참여했고, 논문은 상용 모델명을 적지 않는다.",
        bg=[
            "악력 변화가 곧 쓸 수 있는 동작을 만들지는 않고, 운동 점수가 높아도 컵을 들 수 있다는 뜻은 아니다. 힘과 움직임을 같은 무작위 비교에서 재면, 둘 중 더 나아 보이는 것만 발표하는 일을 피한다.",
            "장갑 논문은 모델을 빠뜨리는 일이 많다. 모델이 없으면 결과를 제품 사양에 옮겨 적을 수 없다. 이 요약은 그래서 논문이 실제로 준 대조에 머문다.",
        ],
        device="",
        design="로봇 훈련 장갑 연습과 대조 조건의 무작위 비교. 공통 결과는 악력과 Fugl-Meyer 운동 점수였고, 95% 신뢰구간이 있는 평균 차로 보고되었다.",
        sample="뇌졸중 후 30명, 각 집단 15명. 논문은 시판 모델을 밝히지 않는다. 일반 장갑 사진은 도해이지 기기 식별이 아니다.",
        result="보고된 집단 간 평균 차는 악력 1.87(95% CI 0.39–3.35, P=0.015), Fugl-Meyer 16.67(95% CI 3.9–29.4, P=0.012)이다. 평균 차는 각 사람의 향상이 아니다. 운동 점수 구간은 넓다. 추정이 정밀하지 않은 작은 표본의 모습이다.",
        sig=[
            "차와 구간을 함께 내는 편이 «대조보다 낫다»는 문장보다 쓸 만하다. 방향이 보이고 불확실성도 보인다.",
            "모델명이 없으므로 이 결과를 특정 Syrebo 장갑의 사양이나 적응증으로 다시 말할 수 없다. 30명은 표본 잡음의 여지도 남긴다.",
        ],
        limit="작은 표본(n=30). 모델이 확인되지 않았고 사진은 일치가 아니다. 평균 차와 P값은 연구의 통계다.")

    add(5, "ko",
        title="초기 아급성기 손 기능: 화산 병원 팀의 SY-HR03E 단일맹검 파일럿 RCT",
        desc="BioMedical Engineering OnLine의 단일맹검 파일럿 RCT. 입원 환자 20명, SY-HR03E, 4주. 논문은 전원 완료, 이상반응 없음, 손 점수와 일상 활동의 예비 신호를 보고한다.",
        lead="초기 아급성기에서 첫 질문은 점수가 몇 점 오를 수 있느냐가 아니다. 세션을 끝낼 수 있는지, 안전한지다. 푸단대학 부속 화산병원 자지에(贾杰) 교수 팀이 그 시기의 손 재활을 위한 Syrebo SY-HR03E 단일맹검 파일럿 무작위 연구를 BioMedical Engineering OnLine에 발표했다. 논문은 20명 전원이 탈락과 이상반응 없이 4주를 마쳤다고 보고한다. 손 점수는 양 집단에서 향상되었고 장갑군에서 변화가 더 컸다. 일상 활동의 집단 내 변화는 장갑군에서 통계적 유의에 이르렀다.",
        bg=[
            "팔과 손은 대개 걷기보다 늦게 회복된다. 식사, 옷 입기, 씻기는 힘의 숫자 하나가 아니라 분절된 손가락 움직임에 기대다. 통상 손 치료는 도움이 되지만, 치료사가 줄 수 있는 반복 횟수는 제한되고 같은 동작을 침상 곁에서 반복하기는 어렵다.",
            "공압 장갑은 손 위의 질량이 작은 채로 손가락을 굽히고 펼 수 있어 침상 곁 사용이 이야기된다. 초기 아급성기 환자는 저절로도 회복한다. 어떤 «예비 효과»도 그 배경에 비추어 읽어야 한다. 파일럿 무작위 연구는 프로토콜이 실행 가능한지 보이고, 더 큰 연구를 위한 신호를 남긴다. 확증 연구를 대신하지 않는다.",
        ],
        device="논문은 SY-HR03E를 상용 소프트 장갑과 탁상 제어기로 기술한다. 보고된 질량은 시스템 약 3.5 kg, 장갑 약 110 g이다. 손등 공압 벨로우즈가 굴곡과 신전을 돕는다. 압력 센서는 사람이 움직이려 할 때의 변화를 본다. 미리 정한 0.7 kPa 역치를 넘으면 제어기는 그 변화를 운동 의도로 보고 팽창하거나 수축한다. 의도한 모드는 능동 보조이지, 완전히 수동적인 끌림이 아니다.",
        design="단일맹검 파일럿 무작위 배정. 로봇군은 표준 재활에 장갑 보조 펴기·쥐기를 더했다. 통상군은 같은 세션 길이의 전통 손 치료를 받았다. 양 집단은 하루 1시간의 표준 재활도 받았다. 치료사가 자세를 감독했다. 등록: ChiCTR2000034614.",
        sample="발병 7일에서 3개월 사이 입원 환자 20명, 각 집단 10명. 장갑 세션은 하루 30분, 주 5일, 4주였다. 한 번의 펴기·쥐기는 약 3초 유지했다. 저자 소속에는 임상 팀과, 논문이 밝힌 대로 Shanghai Siyi Intelligent Technology가 포함된다. 그 관계는 읽는 데 포함된다.",
        result="논문은 20명 전원이 탈락과 이상반응 없이 4주를 마쳤다고 보고한다. 손 Fugl-Meyer 점수는 양 집단에서 향상되었고 로봇군에서 향상이 더 컸다. 수정 Barthel 지수에서는 로봇군의 집단 내 변화만 통계적으로 유의하다고 보고된다(p<0.001). 통상군의 집단 내 변화는 그렇지 않다. 손 Brunnstrom 단계도 로봇군에서만 유의한 집단 내 변화를 보였다. 10 대 10 파일럿에서 집단 내 P값은 신호이지, 일상 기능이 환자 일반에서 오른다는 증거가 아니다.",
        sig=[
            "소프트 장갑 연구의 다수는 만성기 환자를 등록한다. 이 파일럿은 실행 가능성과 안전 질문을 발병 7일에서 3개월 사이로 옮긴다. 만성기 효능 주장을 앞당기지 않는다.",
            "손 점수와 일상 활동 점수는 같은 통계 형태를 취하지 않았다. 논문은 유의한 집단 내 Barthel 변화를 장갑군에서만 보고한다. 그 분리는 다시 시험할 가치가 있다. 일상생활 활동이 해결되었다는 진술이 아니다. 110 g 장갑과 의도 감지는 침상 곁, 나중에는 가정 논의를 가능하게 한다. 이 연구 자체는 입원 환자에서 이루어졌다.",
        ],
        limit="파일럿 무작위 배정, 집단당 10명. 예비 신호는 더 큰 표본이 필요하다. P값은 그 결과에 대한 논문의 보고다. 기기 관련 소속이 공개되어 있으며 함께 저울질해야 한다.")

    add(6, "ko",
        title="담어저락 변증의 손 장애: 장갑과 전침의 200명 네 군 연구",
        desc="Journal of Hunan University of Chinese Medicine. 200명, 네 군. 보고된 총유효율은 88%, 76%, 77.6%, 70.8%. 이 수치는 연구의 복합 지표이지 제품 비율이 아니다.",
        lead="로봇 장갑과 전침을 한 계획에 넣는 것은 구체적인 통합 선택이며, 결과는 그것을 만든 군에 붙어 있어야 한다. 2022년 Journal of Hunan University of Chinese Medicine의 네 군 연구는 담어저락(phlegm-stasis blocking collaterals) 변증의 뇌졸중 후 손 장애 200명을 등록하고, 장갑과 전침, 장갑만, 전침만, 통상 재활을 비교했다. 논문 자신의 «총유효율»은 88%, 76%, 77.6%, 70.8%다. 이 복합 지표는 저자의 요약이다. 제품 유효율이 아니다.",
        bg=[
            "이 변증에서는 현대 재활과 전침을 함께 쓰는 경로가 흔하다. 네 군 배치는 전후 비교만 있는 이야기 대신, 병용, 기기만, 침만, 통상 돌봄을 한 척도에서 보여 줄 수 있다.",
            "총유효율은 여러 판단을 한 퍼센트로 접는다. 거친 대조에는 쓸모 있고, 이름 있는 척도에서 한 사람의 변화로는 쓸모없다. «장갑의 유효율은 88%»라고 인용할 수 없다.",
        ],
        device="",
        design="네 군: 로봇 장갑과 전침, 장갑만, 전침만, 통상 재활. 여기서 다루는 결과는 논문의 총유효율이다. 저자 소속에는 Shanghai Siyi Intelligent Technology가 있고 공동저자로 Yin Ganggang이 있다. 그 공개는 읽기에 남는다.",
        sample="담어저락 변증의 뇌졸중 후 손 장애 200명. 이 칼럼에서 가장 큰 표본이다. 논문은 현재 제품과 맞출 모델명을 적지 않으며, 일반 사진은 그런 일치가 아니다.",
        result="보고된 총유효율은 장갑과 전침 88%, 장갑만 76%, 전침만 77.6%, 통상 재활 70.8%다. 병용군 복합 지표가 더 높다는 것은, 이 연구의 규칙 아래 그 군이 더 높게 나왔다는 뜻일 뿐이다. 88%를 장갑에 돌리지 않으며, 76%는 제품 비율이 아니다. 장갑만과 전침만의 수치는 서로 가까워, 전체 양상을 한 성분으로 설명하는 데도 맞지 않는다.",
        sig=[
            "200명과 네 군은 제품 페이지용 퍼센트가 아니라 비교 가능한 복합 지표를 준다. 총유효율로 읽으면 병용, 단일 수단, 통상 돌봄 사이의 간격은 제한적이다.",
            "여기서 요약된 논문은 칼럼의 다른 연구가 쓰는 같은 평균 차를 주지 않는다. 그 척도가 테이블에 오르기 전에는, 이 연구는 손 점수가 몇 점 오를지가 아니라 성분을 어떻게 묶었는지에 관한 것이다.",
        ],
        limit="퍼센트는 연구 자신의 총유효율이다. 병용군을 장갑만 또는 전침만에 돌릴 수 없다. 모델명은 없다.")

    add(7, "ko",
        title="중대뇌동맥 경색 뒤의 손 재활: 66세 환자 한 명의 증례",
        desc="Cureus 증례. 양측 MCA 영역 경색의 66세 여성이 임상 감독 아래 Syrebo 장갑 프로그램을 받았다. 단일 증례는 일반 결과가 아니다.",
        lead="무작위 연구는 평균 차이를 기술한다. 증례는 한 사람의 재활이 어떻게 짜였는지를 기술한다. 2024년 Cureus에서 Sharma 등은 중대뇌동맥 영역 경색이 있는 66세 여성이 Syrebo 장갑 프로그램을 중심으로 한 신경물리치료를 받았다고 보고했다. 보고는 관찰과 기능 변화의 과정을 따른다. 한 증례이며 일반화되지 않는다.",
        bg=[
            "이 영역의 경색은 팔과 손을 언어나 인지와 함께 건드리는 일이 많아, 계획은 약한 손 이상이다. 가족에게 필요한 것은 퍼센트보다, 장갑 연습이 물리치료의 어디에 있었고 누가 감독했는지인 경우가 많다.",
            "증례는 그 순서를 적을 수 있다. 평행 대조가 없으므로 전후 변화는 자연 회복, 통상 돌봄, 장갑을 섞는다. 그 조각은 분리되지 않는다.",
        ],
        device="논문은 Syrebo 장갑 프로그램을 논의하며 모델명을 적지 않는다. 장갑과 본체 사진은 그 오픈액세스 보고의 그림 2(CC BY 4.0)이며 위 발췌에 있다. 다른 종설의 그림이 아니다.",
        design="단일 증례 보고이지 무작위 연구가 아니다. 의학적 안정 뒤 임상의가 Syrebo 장갑 프로그램을 포함한 신경물리치료를 제공했다.",
        sample="양측 MCA 영역 경색의 66세 여성. 보고는 관찰과 기능 변화를 기록한다. 집단 간 통계는 제공하지 않는다.",
        result="보고의 가치는 돌봄의 과정이지 향상률이 아니다. 심한 경색이 있는 한 사람의 재활 안에 소프트 장갑이 전문가 감독 아래 어떻게 놓였는지를 보여 준다. 단일 증례의 변화는 약속된 회복 정도가 아니다.",
        sig=[
            "대부분이 무작위 연구인 칼럼에서 증례 하나는, 프로그램이 한 사람에게 어떻게 쓰였는지를 보이려 여기 있다. 서사의 빈칸을 채운다. 근거 수준을 올리지 않는다.",
            "한 증례는 이상반응이 얼마나 자주 나는지 추정할 수 없고, 급성·아급성·만성 중 어디가 더 맞는지 말할 수 없다. 그 질문은 대조 연구에 남는다.",
        ],
        limit="단일 증례. 일반 효과가 아니다. 기능 변화를 장갑만에 돌릴 수 없다.")

    add(8, "ko",
        title="뇌졸중 후 상지 장애: 혁신 거울 치료의 60명 무작위 연구",
        desc="New Medicine, 2024. 60명, 4주. 논문은 혁신 거울 치료가 통상 거울 치료보다 FMA-UE, FMA-WH, 수정 Barthel 지수에서 더 큰 향상을 보였다고 보고한다.",
        lead="통상 거울 치료는 거울로 마비된 손이 움직이는 것처럼 보이게 한다. 혁신 방식은 로봇 장갑이 거울이 보여 주는 같은 동작을 마비된 손에 수행하게 해, 보는 것과 하는 것이 세션을 나눈다. 2024년 New Medicine은 Chen 등이 두 방식을 60명에서 4주 비교한 무작위 연구를 실었다. 논문은 상지 운동, 손목-손 운동, 일상 활동에서 혁신 거울 치료의 향상이 더 컸다고 보고한다.",
        bg=[
            "거울 치료에는 알려진 한계가 있다. 마비된 손이 움직이지 않으면 시각 제안에 짝이 되는 운동 입력이 없다. 보조된 굴곡과 신전을 거울 과제에 잇는 것은, 치료사가 정한 범위 안에서 마비측이 실제로 동작을 끝내게 하려는 시도다.",
            "그 변화가 점수에 나타나는지는 아무것도 하지 않는 쪽이 아니라 통상 거울 치료와 비교해 시험해야 한다. 고르게 나뉜 60명은 예비적인 무작위 규모다.",
        ],
        device="학술지 페이지의 훈련 그림에 Yisheng(羿生) 표지가 보인다. 칼럼은 그 표지를 공식 자료의 SY-HR08E에 대응하고, 화면·본체·장갑이 있는 제품 사진을 보여 준다. 대응은 식별 메모이지, 연구 등록처럼 인쇄된 모델 주장이 아니다.",
        design="난수 배정. 거울 과제와 로봇 장갑을 결합한 혁신 거울 치료를 통상 거울 치료와 비교했다. 결과에는 FMA-UE, FMA-WH, 수정 Barthel 지수가 포함되었다.",
        sample="뇌졸중 후 상지 장애 60명, 각 집단 30명, 4주.",
        result="논문은 혁신 거울 치료가 FMA-UE, FMA-WH, 수정 Barthel 지수에서 더 큰 향상을 보였다고 보고한다. 연구의 집단 간 기술이다. 평균과 P값은 이 페이지에서 다시 계산하지 않는다. 학술지 페이지를 아직 확인하는 동안 그 숫자는 논문에 남긴다.",
        sig=[
            "질문은 거울과 맞는 보조 동작을 더하면 거울만과 비교해 점수가 달라지는가다. 60명은 예비 대조를 줄 뿐, 가정 프로그램의 증명이 아니다.",
            "학술지 그림을 SY-HR08E에 잇는 일은 독자가 기기를 알아보게 도울 뿐이다. 점수 차가 안정한지는 전체 숫자의 독립 확인을 기다린다.",
        ],
        limit="집단당 30명. 차이는 논문을 따른다. 평균과 P값은 여기서 다시 계산하지 않는다. 모델 연결은 학술지 그림과 공식 자료 사이의 확인이다.")

    add(9, "ko",
        title="MCA 경색 후 좌측 편마비: 파라딕 자극과 로봇 손의 한 기록",
        desc="IJPRCP 증례. 좌측 편마비의 60세 남성이 뇌졸중 약 3개월 뒤 파라딕 자극과 Syrebo C12를 주 5회, 4주 시작했다. 결합 증례 하나는 어느 한쪽 성분에 돌리지 않는다.",
        lead="편마비 손에는 때로 두 입력이 동시에 주어진다. 근육을 향한 전기 자극과, 손가락을 펴고 쥐는 로봇 손이다. 2025년 International Journal of Physiotherapy Research and Clinical Practice의 증례는 좌측 편마비 남성에서 파라딕 자극과 Syrebo C12의 4주를 기록한다. 결합 계획의 기록이지, 어느 한쪽의 효능 시험이 아니다.",
        bg=[
            "뇌졸중 후 몇 달이 지나면 손의 변화는 대개 느려지고, 임상의는 보통 연습에 자극이나 외부 도움을 더하기도 한다. 둘을 함께 쓰면 전후 변화를 어느 한쪽에 깨끗이 줄 수 없다.",
            "기록은 여전히 쓸모 있다. 계획이 언제 시작했는지, 얼마나 자주 돌았는지, 방에 어떤 기기가 있었는지를 적는다. 비율을 주지 않고, 대조와의 차이도 주지 않는다.",
        ],
        device="기록의 로봇 기기는 Syrebo C12다. 사진은 본체와 장갑을 알아보게 공식 C12 제품 페이지에서 자른 것이다. 논문이 빠뜨린 사양을 더하지 않는다.",
        design="단일 결합 중재: 파라딕 자극과 Syrebo C12 로봇 손 연습을 함께. 평행 대조군은 없다.",
        sample="좌측 편마비의 60세 남성. 계획은 뇌졸중 후 3개월 2주에 시작했고, 주 5회, 4주였다.",
        result="이 페이지는 칼럼을 위해 논문과 대조하지 않은 기능 점수를 다시 싣지 않는다. 분명한 것은 배치다. 자극과 로봇 연습을 함께 썼으므로, 변화를 C12만의 효과나 자극만의 효과로 쓸 수 없다.",
        sig=[
            "기록은 구체적인 일정을 더한다. 뇌졸중 약 3개월 뒤, 주 5회, 두 수단을 함께. 근거 수준을 올리지 않는다.",
            "MCA 경색 후 좌측 편마비 한 증례는 다른 병변이나 다른 시기를 대신하지 않는다.",
        ],
        limit="단일 결합 증례. 변화는 C12에도 자극에도 돌리지 않으며 일반 효과가 아니다.")

    add(10, "ko",
        title="소프트 손목-손 보조기: Wearable Technologies의 설계와 예비 평가",
        desc="Ledoux와 Barth가 Wearable Technologies에 자신들의 3D 프린트 손목-손 보조기를 보고했다. 이 글은 그 설계 논문에 머문다. 상용 제품을 순위 매기지 않으며 효능 시험이 아니다.",
        lead="2024년 Cambridge University Press의 Wearable Technologies는 밴더빌트 대학 Ledoux와 Barth의 설계 논문을 실었다. 그들이 만들고 예비 평가한 기기는 자신들의 3D 프린트 손목-손 파악 보조기다. 논문은 착용형 손을 논의하며 상용 소프트 구조를 언급한다. 이 칼럼은 그 논의를 순위로 바꾸지 않으며, 논문을 Syrebo의 효능 근거로 다루지 않는다.",
        bg=[
            "치료실을 떠나는 손 기기는 무게, 윤곽, 사람이 스스로 착용할 수 있는지를 답해야 한다. 설계 논문은 대개 그 제약을 적고 나서 시제품을 기술한다. 다기관 기능 시험을 먼저 보고하지 않는다. 설계 논문을 효능 논문처럼 읽으면 측정되지 않은 임상 종료점을 만들어 낸다.",
            "소프트 구조와 강성 외골격은 다른 공학 문제에 답한다. 유연함은 윤곽을 줄이는 한 방법이다. 기능 변화를 말하려면 여전히 사람 대상 연구가 따로 필요하다.",
        ],
        device="위 발췌는 오픈액세스 첫 페이지(CC BY 4.0)이지 비교표가 아니다. 제품 사진은 Syrebo 임상 장갑 시스템을 보여 준다. 이 실험의 그림이 아니다.",
        design="저자 자신의 3D 프린트 보조기에 대한 설계, 모델링, 예비 평가. 논문은 Syrebo의 무작위 연구가 아니고, 시판 기기 사이의 효능 비교도 아니다.",
        sample="사람 부분은 저자 시제품에 대한 예비 관찰이다. 규모와 과제는 논문의 것이다. 여기서 Syrebo 코호트로 다시 쓰지 않는다.",
        result="이 페이지는 상용 형용사를 인용하지 않고 다른 상표를 나열하지 않는다. 남는 것은, 논문이 소프트하고 착용 가능한 구조에 관한 오픈액세스 설계 연구라는 점이다. 저자의 «presumably»는 편안함을 측정된 종료점으로 다루지 않았음을 표시한다.",
        sig=[
            "논문이 칼럼에 있는 이유는 설계 연구가 효능 시험과 구분되어 남게 하려는 것이다. 소프트 구조가 일상에서 기기를 더 쉽게 착용하게 하는지는 착용 연구와 기능 연구가 따로 답한다.",
            "오픈액세스는 독자가 문장을 확인할 수 있게 한다. 확인의 목적은 추정을 결론으로 만들지 않는 것이지, 가장 가벼운 제품을 뽑는 것이 아니다.",
        ],
        limit="Syrebo의 효능 시험이 아니고 제품 순위도 아니다. 출처는 편안함을 «presumably»로 한정한다. 첫 페이지 크롭에는 비교표가 없다.")

    add(11, "ko",
        title="가정용으로 구상된 손가락 로봇: 일본로봇학회지의 개발 기록",
        desc="2023년 일본로봇학회지 논문은 편마비용 가정용 손가락 로봇을 논의하고, 상품화된 소수 사례 중 하나로 Syrebo를 적는다. 임상시험이 아니다.",
        lead="가정 손 재활은 여러 해 이야기되어 왔다. 학회 문헌에서 상품화된 사례는 아직 적다. 2023년 일본로봇학회지는 Furudate 등의 논문을 실었다. 편마비 후 가정 사용을 위한 손가락 재활 로봇과, 임상의와 함께한 개발에 관한 글이다. 저자는 상품화된 가정용 사례가 드물다고 적고, Syrebo 손 장갑을 그런 사례의 하나로 든다. 개발과 협력의 기록이지 효능 시험이 아니다.",
        bg=[
            "병동과 가정 사이에는 착용, 안전 한계, 치료사가 방에 없을 때의 사용이 있다. 공학 논문은 그 제약을 임상의와의 작업 안에 둔다. 이름이 나온다는 것은 저자가 이 제품을 예로 골랐다는 뜻이다. 학회가 대조 연구를 했다는 뜻은 아니다.",
            "«상품화된 것이 적다»는 것 또한 한계다. 이를 «가정 재활이 이미 일반적으로 가능하다»로 읽으면 예를 역학적 주장으로 바꾼다.",
        ],
        device="논문은 장갑 사진을 싣지 않는다. 이 칼럼의 장갑과 본체 이미지는 Sharma 등의 2024년 Cureus 증례 그림 2(CC BY 4.0)다. 캡션이 그렇게 적는다. 일본 학회 논문의 원그림이 아니다.",
        design="가정용 손가락 로봇과 임상의와의 작업에 관한 학회지 개발 논문. 무작위 배정도 없고 집단 간 기능 비교도 없다.",
        sample="임상 표본 크기는 적용되지 않는다. 논문은 코호트의 결과가 아니라 제품으로 가는 경로를 논의한다.",
        result="여기서 쓰는 진술은, 가정을 겨냥해 상품화된 손가락 로봇은 아직 적고 Syrebo는 저자가 든 한 예라는 것이다. 칼럼은 그 범위를 유지한다. 효능, 시장 순위, 또는 가정 훈련을 마칠 것이라는 약속으로 다시 쓰지 않는다.",
        sig=[
            "기록의 가치는 가정 사용을 임상의와 함께 정의하는 공학 문제로 다룬다는 점이다. 상품화된 예는 한 기기가 시제품에서 제품으로 옮겼음을 보여 준다.",
            "집에서 안전하고 반복해서 쓸 수 있는지는 여전히 적응증, 감독, 별도의 임상 연구에 달렸다. 학회 논문은 그 자료를 제공하지 않는다.",
        ],
        limit="Syrebo의 임상시험이 아니다. 출처는 상품화 사례가 적다고 강조한다. 사진은 다른 오픈액세스 증례에서 왔다.")
